  function star(cx, cy, ro, ri, n, a0){ var s = ""; for (var i = 0; i < 2 * n; i++){ var r = i % 2 ? ri : ro, a = a0 + i * Math.PI / n;
    s += (i ? "L" : "M") + r2(cx + r * Math.cos(a)) + " " + r2(cy + r * Math.sin(a)); } return s + "Z"; }
  function flower(cx, cy, r, n){ var s = "", k = r * 0.62; for (var i = 0; i <= n; i++){ var a = -Math.PI / 2 + i * 2 * Math.PI / n;
    var x = r2(cx + r * Math.cos(a)), y = r2(cy + r * Math.sin(a)); s += i ? ("A" + k + " " + k + " 0 0 1 " + x + " " + y) : ("M" + x + " " + y); } return s + "Z"; }
  function almond(x, y){ return "M" + x + " " + y + "c-4 3-6 9-5 14 1 3 3 4 5 4s4-1 5-4c1-5-1-11-5-14z"; }
  function tip(x, y){ return "M" + x + " " + y + "c2.2 2 2.8 5.2 1.4 8h-2.8c-1.4-2.8-.8-6 1.4-8z"; }
  function needles(x1, y1, x2, y2, n, L){ var s = "M" + x1 + " " + y1 + "L" + x2 + " " + y2, dx = x2 - x1, dy = y2 - y1, len = Math.hypot(dx, dy), ux = dx / len, uy = dy / len;
    for (var i = 1; i < n; i++){ var t = i / n, px = x1 + dx * t, py = y1 + dy * t;
      s += "M" + r2(px) + " " + r2(py) + "l" + r2((-uy + ux * .6) * L) + " " + r2((ux + uy * .6) * L) + "M" + r2(px) + " " + r2(py) + "l" + r2((uy + ux * .6) * L) + " " + r2((-ux + uy * .6) * L); }
    return s; }
